def separate_paren_groups(paren_string: str) -> List[str]:
    def extract_groups(paren_string):
        groups = []
        group = ""
        open_count = 0
        for char in paren_string:
            if char == '(':
                open_count += 1
                if open_count == 1:
                    group += char
            elif char == ')':
                open_count -= 1
                if open_count == 0:
                    group += char
                    groups.append(group)
                    group = ""
            else:
                if open_count > 0:
                    group += char
        return groups

    def remove_spaces(groups):
        return [group.replace(" ", "") for group in groups]

    def separate_groups(groups):
        return groups

    def check_balanced(groups):
        return all(group.count('(') == group.count(')') for group in groups)

    groups = extract_groups(paren_string)
    groups = remove_spaces(groups)
    groups = separate_groups(groups)

    if not check_balanced(groups):
        raise ValueError("Unbalanced parentheses in input string")

    return groups

